def skill():
    a4 = Rational(1265, 55)
    for d in range(0, 8):
        if (a4 + 5*d) % 7 == 0 and a4 - 3*d > 0:
            return a4 + 8*d

def standard():
    res = set()
    for a1 in range(1, 400):
        for d in range(0, 200):
            S = lambda k: k*a1 + k*(k - 1)//2*d
            if sum(S(k) for k in range(1, 11)) == 1265 and (a1 + 8*d) % 7 == 0:
                res.add(a1 + 11*d)
    assert len(res) == 1
    return list(res)[0]

def unique():
    return [standard()]
